package com.sistemahospitalar.hospital.service; import com.sistemahospitalar.hospital.model.Paciente; import com.sistemahospitalar.hospital.repository.PacienteRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class PacienteService {private final PacienteRepository repo; public PacienteService(PacienteRepository repo){this.repo=repo;} public List<Paciente> listar(){return repo.findAll();} public Paciente salvar(Paciente p){return repo.save(p);} public Paciente buscar(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Paciente não encontrado."));}}
